//! Annotated spectra for xiVIEW's spectrum viewer (xiSPEC), in the form the
//! Rappsilber lab's annotator answers (`Peptides`, `LinkSite`, `peaks` with
//! their isotope `clusters`, `fragments` with the clusters they matched,
//! `annotation`).
//!
//! The fragments are generated by Annotator's engine (`mzcore` /
//! `mzannotate`), as in garlic's own viewer; MS-cleavable linker stub ions
//! come from the viewer's own search for them ([`model::annotate`]), which
//! is only called, not changed.

use super::data::Layout;
use crate::viewer::model::{self, Kind, Match, Model, Peaks, Results, StubIonKind};
use mzannotate::fragment::FragmentType;
use mzannotate::prelude::*;
use mzcore::chemistry::{NeutralLoss, OutputMolecularFormula};
use mzcore::prelude::*;
use mzcore::system::isize::Charge;
use sage_core::mass::Tolerance;
use serde_json::{json, Map, Value};
use std::collections::{BTreeMap, BTreeSet, HashMap};

const PROTON: f64 = 1.007_276_466_6;
/// Spacing of isotope peaks (13C - 12C)
const NEUTRON: f64 = 1.003_354_84;

/// A garlic match behind a request: its exact peptidoform (labels and
/// modifications as searched) and link, for the stub ions
pub struct Known<'a> {
    pub results: &'a Results,
    pub m: &'a Match,
    /// Multivalent species: every peptide and link as xiSPEC shows them
    pub layout: Option<&'a Layout>,
}

/// Ion types xiSPEC asks for (`BIon`, `PeptideIon`, ...)
#[derive(Clone, Debug, Default)]
struct Ions {
    series: BTreeSet<char>,
    precursor: bool,
}

impl Ions {
    fn from_request(ions: Option<&Value>) -> Ions {
        let mut out = Ions::default();
        for t in ions.and_then(Value::as_array).into_iter().flatten() {
            let Some(t) = t.get("type").and_then(Value::as_str) else { continue };
            match t.to_ascii_lowercase().trim_end_matches("ion") {
                "peptide" | "precursor" => out.precursor = true,
                s if s.len() == 1 && "abcxyz".contains(s) => {
                    out.series.insert(s.chars().next().unwrap_or('b'));
                }
                _ => {}
            }
        }
        if out.series.is_empty() && !out.precursor {
            out.series.extend(['b', 'y']);
        }
        out
    }

    /// Annotator's CID model has a, b, y; anything else needs all ion types
    fn model(&self) -> &'static FragmentationModel {
        if self.series.iter().all(|c| "aby".contains(*c)) {
            FragmentationModel::cid()
        } else {
            FragmentationModel::all()
        }
    }
}

/// A number, or a number written as text (xiSPEC's settings send text)
fn number(v: &Value) -> Option<f64> {
    match v {
        Value::String(s) => s.trim().parse().ok(),
        v => v.as_f64(),
    }
}

/// The fragment tolerance of a request (`{"tolerance": 20, "unit": "ppm"}`)
fn tolerance(request: &Value) -> Tolerance {
    let t = &request["annotation"]["fragmentTolerance"];
    let value = number(&t["tolerance"]).unwrap_or(20.0) as f32;
    let unit = t["unit"].as_str().unwrap_or("ppm").to_ascii_lowercase();
    if unit.starts_with("da") || unit == "th" || unit == "m/z" {
        Tolerance::Da(-value, value)
    } else {
        Tolerance::Ppm(-value, value)
    }
}

fn within(tolerance: Tolerance, theoretical: f64, observed: f64) -> bool {
    match tolerance {
        Tolerance::Ppm(lo, hi) => ((observed - theoretical) / theoretical * 1e6).abs() <= lo.abs().max(hi.abs()) as f64,
        Tolerance::Da(lo, hi) | Tolerance::Pct(lo, hi) => (observed - theoretical).abs() <= lo.abs().max(hi.abs()) as f64,
    }
}

fn error(tolerance: Tolerance, theoretical: f64, observed: f64) -> (f64, &'static str) {
    match tolerance {
        Tolerance::Ppm(..) => ((observed - theoretical) / theoretical * 1e6, "ppm"),
        _ => (observed - theoretical, "Da"),
    }
}

/// The residues of each request peptide, with the modification named after
/// each (`(oxidation)`, empty if none)
fn request_peptides(request: &Value) -> Vec<Vec<(char, String)>> {
    request["Peptides"]
        .as_array()
        .into_iter()
        .flatten()
        .map(|p| {
            p["sequence"]
                .as_array()
                .into_iter()
                .flatten()
                .map(|r| {
                    (
                        r["aminoAcid"].as_str().and_then(|s| s.chars().next()).unwrap_or('X'),
                        r["Modification"].as_str().unwrap_or("").to_string(),
                    )
                })
                .collect()
        })
        .collect()
}

/// ProForma of a request alone (no garlic match behind it): modifications
/// and the linker as masses
fn request_proforma(request: &Value) -> Result<String, String> {
    let peptides = request_peptides(request);
    if peptides.is_empty() {
        return Err("the request has no peptides".into());
    }
    let mut mod_mass: BTreeMap<String, f64> = BTreeMap::new();
    for m in request["annotation"]["modifications"].as_array().into_iter().flatten() {
        if let (Some(id), Some(mass)) = (m["id"].as_str(), number(&m["mass"])) {
            mod_mass.insert(id.to_string(), mass);
        }
    }
    let linker = number(&request["annotation"]["crosslinker"]["modMass"]).unwrap_or(0.0);
    let sites: Vec<(usize, usize)> = request["LinkSite"]
        .as_array()
        .into_iter()
        .flatten()
        .filter_map(|l| Some((number(&l["peptideId"])? as usize, number(&l["linkSite"]).filter(|&s| s >= 0.0)? as usize)))
        .collect();
    let crosslinked = peptides.len() > 1 && sites.len() > 1;
    let mut text = Vec::new();
    for (p, residues) in peptides.iter().enumerate() {
        let mut s = String::new();
        for (i, (aa, name)) in residues.iter().enumerate() {
            s.push(*aa);
            if !name.is_empty() {
                let mass = mod_mass
                    .get(name)
                    .copied()
                    .or_else(|| name.trim_matches(|c| c == '(' || c == ')').parse().ok())
                    .ok_or_else(|| format!("unknown modification {name}"))?;
                s.push_str(&format!("[{mass:+}]"));
            }
            if sites.contains(&(p, i)) {
                if crosslinked {
                    s.push_str(&if p == 0 { format!("[{linker:+}#XL1]") } else { "[#XL1]".to_string() });
                } else if linker != 0.0 {
                    // one peptide: the linker as a modification of its site
                    s.push_str(&format!("[{linker:+}]"));
                }
            }
        }
        text.push(s);
    }
    Ok(text.join("//"))
}

/// Neutral losses of a fragment as xi names them: `H2O` / `NH3` and counts
fn losses(f: &Fragment<OutputMolecularFormula>) -> BTreeMap<String, u16> {
    let mut out = BTreeMap::new();
    for loss in &f.neutral_loss {
        let (name, n) = match loss {
            NeutralLoss::Loss(n, formula) => (formula.hill_notation(), *n),
            NeutralLoss::Gain(n, formula) => (format!("+{}", formula.hill_notation()), *n),
            NeutralLoss::SideChainLoss(formula, _) => (formula.hill_notation(), 1),
        };
        let name = match name.as_str() {
            "H2O1" | "H2O" => "H2O".to_string(),
            "H3N1" | "H3N" | "NH3" => "NH3".to_string(),
            other => other.replace('1', ""),
        };
        *out.entry(name).or_insert(0) += n.max(1);
    }
    out
}

/// One xiSPEC fragment (an ion identity) and the clusters it matched
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
struct Key {
    /// `b`, `y`, `P`
    kind: String,
    number: usize,
    peptide: usize,
    /// The other peptides (xiSPEC rows) it carries through the links
    carried: Vec<usize>,
    losses: Vec<(String, u16)>,
    /// Stub names (MS-cleavable linkers), `A`, `A+S`
    stub: String,
}

impl Key {
    fn name(&self) -> String {
        let mut name = if self.kind == "P" { "P".to_string() } else { format!("{}{}", self.kind, self.number) };
        match self.carried.len() {
            0 => {}
            1 => name.push_str("+P"),
            n => name.push_str(&format!("+{n}P")),
        }
        if !self.stub.is_empty() {
            name.push('+');
            name.push_str(&self.stub);
        }
        for (loss, n) in &self.losses {
            name.push_str(&format!("_{loss}x{n}"));
        }
        name
    }
}

#[derive(Clone, Debug)]
struct Hit {
    cluster: usize,
    calc_mz: f64,
    error: f64,
    unit: &'static str,
    charge: u8,
}

/// Isotope clusters, built around the peaks fragments matched (as garlic's
/// viewer matches them: the nearest peak within tolerance): the peak and
/// the isotope peaks that follow it at the fragment's charge. A peak can be
/// in several; peaks no fragment matched are clusters of their own (charge 0).
#[derive(Default)]
struct Clusters {
    list: Vec<(u8, Vec<usize>)>,
    index: HashMap<(usize, u8), usize>,
}

impl Clusters {
    fn of(&mut self, peak: usize, z: u8, mz: &[f64], intensity: &[f32], tolerance: Tolerance) -> usize {
        if let Some(&c) = self.index.get(&(peak, z)) {
            return c;
        }
        let mut chain = vec![peak];
        while chain.len() < 6 {
            let last = chain[chain.len() - 1];
            let target = mz[last] + NEUTRON / z.max(1) as f64;
            let Some(j) = nearest(mz, target, tolerance).filter(|&j| j > last) else { break };
            // isotope peaks of peptides fall off after the first few
            if intensity[j] > intensity[last] * 4.0 {
                break;
            }
            chain.push(j);
        }
        self.list.push((z, chain));
        self.index.insert((peak, z), self.list.len() - 1);
        self.list.len() - 1
    }

    /// Every peak in a cluster, ordered by first peak; `map` gives the new
    /// id of each cluster made so far
    fn finish(mut self, peaks: usize) -> (Vec<(u8, Vec<usize>)>, Vec<usize>) {
        let mut covered = vec![false; peaks];
        for (_, members) in &self.list {
            for &p in members {
                covered[p] = true;
            }
        }
        let made = self.list.len();
        for (p, _) in covered.iter().enumerate().filter(|(_, c)| !**c) {
            self.list.push((0, vec![p]));
        }
        let mut order: Vec<usize> = (0..self.list.len()).collect();
        order.sort_by_key(|&c| (self.list[c].1[0], self.list[c].0));
        let mut map = vec![0; self.list.len()];
        for (new, &old) in order.iter().enumerate() {
            map[old] = new;
        }
        let list = order.iter().map(|&c| self.list[c].clone()).collect();
        map.truncate(made);
        (list, map)
    }
}

/// The peak nearest to `target` within tolerance; `mz` sorted
fn nearest(mz: &[f64], target: f64, tolerance: Tolerance) -> Option<usize> {
    let i = mz.partition_point(|&m| m < target);
    [i.checked_sub(1), Some(i)]
        .into_iter()
        .flatten()
        .filter(|&j| j < mz.len() && within(tolerance, target, mz[j]))
        .min_by(|&a, &b| (mz[a] - target).abs().total_cmp(&(mz[b] - target).abs()))
}

/// Annotate `peaks` for a xiSPEC `request`. With a garlic match (`known`)
/// its exact peptidoform is used and MS-cleavable stub ions are added;
/// otherwise the request's peptides, modification masses and linker mass.
pub fn annotate(request: &Value, peaks: &Peaks, known: Option<Known>) -> Result<Value, String> {
    let tol = tolerance(request);
    let ions = Ions::from_request(request["annotation"].get("ions"));
    let charge = number(&request["annotation"]["precursorCharge"]).map(|z| z as u8).filter(|&z| z > 0).unwrap_or(2);
    let precursor_mz = number(&request["annotation"]["precursorMZ"]);

    // peaks sorted by m/z (the viewer's stub search returns indices into them)
    let mut order: Vec<usize> = (0..peaks.mz.len()).collect();
    order.sort_by(|&a, &b| peaks.mz[a].total_cmp(&peaks.mz[b]));
    let sorted = Peaks {
        mz: order.iter().map(|&i| peaks.mz[i]).collect(),
        intensity: order.iter().map(|&i| peaks.intensity[i]).collect(),
        precursor_mz: peaks.precursor_mz,
        ion_mobility: peaks.ion_mobility,
    };

    // the peptidoform, the links (engine peptide indices) and the xiSPEC layout
    let (proforma, links, layout, link) = match &known {
        Some(k) => {
            let link = k.results.link(k.m);
            let links = link.as_ref().map(|l| l.links.clone()).unwrap_or_default();
            (k.results.proforma(k.m), links, k.layout, link)
        }
        None => {
            let proforma = request_proforma(request)?;
            let sites: Vec<(usize, usize)> = request["LinkSite"]
                .as_array()
                .into_iter()
                .flatten()
                .filter_map(|l| Some((number(&l["peptideId"])? as usize, number(&l["linkSite"]).filter(|&s| s >= 0.0)? as usize)))
                .collect();
            let links = match sites.as_slice() {
                [(a, sa), (b, sb), ..] if a != b => vec![(*a, *sa, *b, *sb)],
                _ => Vec::new(),
            };
            (proforma, links, None, None)
        }
    };
    let set = PeptidoformIonSet::pro_forma(&proforma, &mzcore::ontology::STATIC_ONTOLOGIES)
        .map_err(|errors| errors.iter().map(|e| e.to_string()).collect::<Vec<_>>().join("; "))?
        .0;
    let residues: Vec<Vec<String>> = set
        .peptidoform_ions()
        .first()
        .map(|ion| {
            ion.peptidoforms()
                .iter()
                .map(|p| p.sequence().iter().map(|s| s.aminoacid.to_string()).collect())
                .collect()
        })
        .unwrap_or_default();
    let fragments = set.generate_theoretical_fragments::<OutputMolecularFormula>(
        Charge::new::<mzcore::system::e>(charge as isize),
        ions.model(),
    );

    let mut clusters = Clusters::default();

    // xiSPEC rows: the layout's order (multivalent species), else as the engine has them
    let order: Vec<usize> = layout.map_or_else(|| (0..residues.len()).collect(), |l| l.order.clone());
    let row = |p: usize| order.iter().position(|&q| q == p).unwrap_or(p);
    // the other peptides (rows) a backbone ion of peptide `p` carries: those
    // linked to a link residue it holds (N-terminal: residues 0..n,
    // C-terminal: len-n..len), and everything linked to them
    let carried = |p: usize, n_term: bool, number: usize| -> Vec<usize> {
        let len = residues.get(p).map_or(0, Vec::len);
        let holds = |s: usize| if n_term { s < number } else { s >= len.saturating_sub(number) };
        let mut queue = Vec::new();
        for &(a, sa, b, sb) in &links {
            if a == b {
                continue;
            }
            if a == p && holds(sa) {
                queue.push(b);
            }
            if b == p && holds(sb) {
                queue.push(a);
            }
        }
        let mut seen = BTreeSet::new();
        while let Some(q) = queue.pop() {
            if q == p || !seen.insert(q) {
                continue;
            }
            for &(a, _, b, _) in &links {
                if a == q {
                    queue.push(b);
                }
                if b == q {
                    queue.push(a);
                }
            }
        }
        let mut rows: Vec<usize> = seen.into_iter().map(row).collect();
        rows.sort_unstable();
        rows
    };
    let mut found: BTreeMap<Key, Vec<Hit>> = BTreeMap::new();
    let mut add = |key: Key, hit: Hit| {
        let hits = found.entry(key).or_default();
        if !hits.iter().any(|h| h.cluster == hit.cluster && h.charge == hit.charge) {
            hits.push(hit);
        }
    };
    for f in &fragments {
        let (kind, number, n_term) = match &f.ion {
            FragmentType::a(p, _) => ('a', p.series_number, true),
            FragmentType::b(p, _) => ('b', p.series_number, true),
            FragmentType::c(p, _) => ('c', p.series_number, true),
            FragmentType::x(p, _) => ('x', p.series_number, false),
            FragmentType::y(p, _) => ('y', p.series_number, false),
            FragmentType::z(p, _) => ('z', p.series_number, false),
            FragmentType::Precursor => ('P', 0, true),
            _ => continue,
        };
        if kind == 'P' && !ions.precursor || kind != 'P' && !ions.series.contains(&kind) {
            continue;
        }
        let engine_peptide = f.peptidoform_index.unwrap_or(0);
        let peptide = if kind == 'P' { 0 } else { row(engine_peptide) };
        let Some(mz) = f.mz(MassMode::Monoisotopic).map(|m| m.value) else { continue };
        let z = f.charge.value.unsigned_abs() as u8;
        let Some(peak) = nearest(&sorted.mz, mz, tol) else { continue };
        let cluster = clusters.of(peak, z, &sorted.mz, &sorted.intensity, tol);
        let (err, unit) = error(tol, mz, sorted.mz[peak]);
        let key = Key {
            kind: kind.to_string(),
            number: if kind == 'P' { residues.first().map_or(0, Vec::len) } else { number },
            peptide,
            carried: if kind == 'P' { (1..residues.len()).collect() } else { carried(engine_peptide, n_term, number) },
            losses: losses(f).into_iter().collect(),
            stub: String::new(),
        };
        add(key, Hit { cluster, calc_mz: mz, error: err, unit, charge: z });
    }

    // MS-cleavable linkers: the stub ions the viewer finds (its own search, unchanged)
    if let (Some(_), Some(link)) = (&known, &link) {
        if !link.stubs.is_empty() {
            if let Ok(a) = model::annotate(&sorted, &proforma, charge, Model::CidHcd, tol, Some(link)) {
                for s in &a.stub_ions {
                    let Some(view) = a.peaks.get(s.peak) else { continue };
                    // the same peak in the sorted list
                    let i = sorted.mz.partition_point(|&m| m < view.mz);
                    if sorted.mz.get(i) != Some(&view.mz) {
                        continue;
                    }
                    let cluster = clusters.of(i, s.charge, &sorted.mz, &sorted.intensity, tol);
                    let stub = s.stubs.iter().filter_map(|&j| link.stubs.get(j)).map(|x| x.name.clone()).collect::<Vec<_>>().join("+");
                    let series = s.text.chars().next().filter(|c| "abcxyz".contains(*c)).unwrap_or('b');
                    let len = |p: usize| residues.get(p).map_or(0, Vec::len);
                    let (kind, number) = match s.kind {
                        StubIonKind::Peptide | StubIonKind::Part { .. } => ("P".to_string(), len(s.peptide)),
                        StubIonKind::NTerm(r) => (series.to_string(), r + 1),
                        StubIonKind::CTerm(r) => (series.to_string(), len(s.peptide).saturating_sub(r)),
                    };
                    let peptide = row(s.peptide);
                    // a multivalent species broken at one linker: the peptides still held together
                    let mut with: Vec<usize> = match s.kind {
                        StubIonKind::Part { peptides, .. } => {
                            (0..8).filter(|&q| peptides & (1 << q) != 0 && q != s.peptide).map(row).collect()
                        }
                        _ => Vec::new(),
                    };
                    with.sort_unstable();
                    let (err, unit) = error(tol, s.theoretical_mz, view.mz);
                    let key = Key { kind, number, peptide, carried: with, losses: Vec::new(), stub };
                    add(key, Hit { cluster, calc_mz: s.theoretical_mz, error: err, unit, charge: s.charge });
                }
            }
        }
    }

    // xiSPEC output
    let (clusters, renumber) = clusters.finish(sorted.mz.len());
    let shown_peptides: Vec<usize> = order.clone();
    let text = |p: usize, from: usize, to: usize| -> String {
        residues.get(p).map(|r| r[from.min(r.len())..(to + 1).min(r.len())].concat()).unwrap_or_default()
    };
    let mut fragments_out = Vec::new();
    for (key, hits) in &found {
        // ranges by xiSPEC peptide
        let engine = shown_peptides.get(key.peptide).copied().unwrap_or(0);
        let len = residues.get(engine).map_or(0, Vec::len);
        let own = match key.kind.as_str() {
            "P" => (0, len.saturating_sub(1)),
            k if "abc".contains(k) => (0, key.number.saturating_sub(1)),
            _ => (len.saturating_sub(key.number), len.saturating_sub(1)),
        };
        let mut ranges: Vec<(usize, usize, usize)> = vec![(key.peptide, own.0, own.1)];
        for &x in key.carried.iter().filter(|&&x| x != key.peptide) {
            let p = shown_peptides.get(x).copied().unwrap_or(x);
            ranges.push((x, 0, residues.get(p).map_or(0, Vec::len).saturating_sub(1)));
        }
        ranges.sort();
        let sequence = ranges
            .iter()
            .map(|&(x, from, to)| text(shown_peptides.get(x).copied().unwrap_or(0), from, to))
            .collect::<Vec<_>>()
            .join(" + ");
        let name = key.name();
        let nlosses: u16 = key.losses.iter().map(|(_, n)| n).sum();
        fragments_out.push(json!({
            "name": name,
            "ionNumber": key.number,
            "peptideId": key.peptide,
            "range": ranges.iter().map(|&(x, from, to)| json!({"peptideId": x, "from": from, "to": to})).collect::<Vec<_>>(),
            "type": key.kind,
            "class": if nlosses > 0 { "lossy" } else { "non-lossy" },
            "nlosses": nlosses,
            "stub": key.stub,
            "clusterIds": hits.iter().map(|h| renumber[h.cluster]).collect::<Vec<_>>(),
            "clusterInfo": hits.iter().map(|h| json!({
                "Clusterid": renumber[h.cluster],
                "calcMZ": h.calc_mz,
                "error": h.error,
                "errorUnit": h.unit,
                "matchedMissingMonoIsotopic": 0,
                "matchedCharge": h.charge,
            })).collect::<Vec<_>>(),
            "sequence": sequence,
        }));
    }

    let mut cluster_of = vec![Vec::new(); sorted.mz.len()];
    for (c, (_, members)) in clusters.iter().enumerate() {
        for &p in members {
            cluster_of[p].push(c);
        }
    }
    let peaks_out: Vec<Value> = sorted
        .mz
        .iter()
        .zip(&sorted.intensity)
        .zip(&cluster_of)
        .map(|((mz, intensity), ids)| json!({"mz": mz, "intensity": intensity, "clusterIds": ids}))
        .collect();
    let clusters_out: Vec<Value> =
        clusters.iter().map(|(z, members)| json!({"charge": z, "firstPeakId": members[0]})).collect();

    // the request's annotation, completed
    let mut annotation: Map<String, Value> = request["annotation"].as_object().cloned().unwrap_or_default();
    // the precursor: garlic's calculated mass, else the peptides and linker
    let mass = match &known {
        Some(k) if k.m.calcmass > 0.0 => Some(k.m.calcmass as f64),
        // each peptide alone with the link marks taken out: the linker mass
        // stays on the first peptide's link residue (`[+158.0038]`)
        _ => proforma
            .split("//")
            .map(|p| {
                let alone = p.replace("#XL1", "").replace("[]", "");
                PeptidoformIonSet::pro_forma(&alone, &mzcore::ontology::STATIC_ONTOLOGIES)
                    .ok()
                    .and_then(|(s, _)| s.formulas().first().map(|f| f.monoisotopic_mass().value))
            })
            .sum(),
    };
    if let Some(mass) = mass {
        let calc = (mass + charge as f64 * PROTON) / charge as f64;
        annotation.insert("calculatedMZ".into(), json!(calc));
        if let Some(observed) = precursor_mz {
            annotation.insert("precursorError".into(), json!({"tolerance": (observed - calc) / calc * 1e6, "unit": "ppm"}));
        }
    }
    annotation.insert(
        "losses".into(),
        json!([
            {"id": "H2O", "specificity": ["S", "T", "D", "E", "CTerm"], "mass": 18.01056027},
            {"id": "NH3", "specificity": ["R", "K", "N", "Q", "NTerm"], "mass": 17.02654493},
        ]),
    );
    annotation.insert("xiVersion".into(), json!(format!("garlic {}", env!("CARGO_PKG_VERSION"))));
    if let Some(l) = &link {
        let mut crosslinker = annotation.get("crosslinker").and_then(Value::as_object).cloned().unwrap_or_default();
        crosslinker.insert("name".into(), json!(l.linker));
        crosslinker.entry("modMass").or_insert(json!(l.linker_mass));
        annotation.insert("crosslinker".into(), Value::Object(crosslinker));
    }

    // the peptides and links shown: a multivalent species whole, a loop-link
    // with both its ends, else as asked
    let (peptides_out, link_sites_out) = match (layout, &known) {
        (Some(l), _) => {
            let mut mods: Vec<Value> = annotation.get("modifications").and_then(Value::as_array).cloned().unwrap_or_default();
            for (name, mass) in &l.modifications {
                if !mods.iter().any(|m| m["id"].as_str() == Some(name)) {
                    mods.push(json!({"id": name, "mass": mass, "aminoAcids": ["*"]}));
                }
            }
            annotation.insert("modifications".into(), Value::Array(mods));
            (l.peptides.clone(), l.link_sites.clone())
        }
        (None, Some(k)) if k.m.kind == Kind::Loop => (
            request["Peptides"].clone(),
            json!([
                {"id": 0, "peptideId": 0, "linkSite": k.m.sites.0.saturating_sub(1)},
                {"id": 0, "peptideId": 0, "linkSite": k.m.sites.1.saturating_sub(1)},
            ]),
        ),
        _ => (request["Peptides"].clone(), request["LinkSite"].clone()),
    };
    Ok(json!({
        "Peptides": peptides_out,
        "LinkSite": link_sites_out,
        "peaks": peaks_out,
        "clusters": clusters_out,
        "fragments": fragments_out,
        "annotation": Value::Object(annotation),
    }))
}

/// Peaks of a request (`[{"mz": .., "intensity": ..}]`)
pub fn request_peaks(request: &Value) -> Peaks {
    let mut mz = Vec::new();
    let mut intensity = Vec::new();
    for p in request["peaks"].as_array().into_iter().flatten() {
        if let (Some(m), Some(i)) = (number(&p["mz"]), number(&p["intensity"])) {
            mz.push(m);
            intensity.push(i as f32);
        }
    }
    Peaks { mz, intensity, precursor_mz: number(&request["annotation"]["precursorMZ"]), ion_mobility: None }
}

#[cfg(test)]
mod test {
    use super::*;

    /// Peaks at the singly charged b and y ions of a peptidoform, plus noise
    fn ions_of(proforma: &str, charge: isize) -> Vec<f64> {
        let set = PeptidoformIonSet::pro_forma(proforma, &mzcore::ontology::STATIC_ONTOLOGIES).unwrap().0;
        let fragments = set.generate_theoretical_fragments::<OutputMolecularFormula>(
            Charge::new::<mzcore::system::e>(charge),
            FragmentationModel::cid(),
        );
        let mut mz: Vec<f64> = fragments
            .iter()
            .filter(|f| matches!(f.ion, FragmentType::b(..) | FragmentType::y(..)) && f.neutral_loss.is_empty())
            .filter(|f| f.charge.value == 1)
            .filter_map(|f| f.mz(MassMode::Monoisotopic).map(|m| m.value))
            .collect();
        mz.sort_by(f64::total_cmp);
        mz.dedup_by(|a, b| (*a - *b).abs() < 1e-6);
        mz
    }

    fn residues(seq: &str) -> Value {
        json!({"sequence": seq.chars().map(|c| json!({"aminoAcid": c.to_string(), "Modification": ""})).collect::<Vec<_>>()})
    }

    /// A crosslink request as xiVIEW sends it (no garlic match behind it):
    /// b/y ions are found, those past the link carry the other peptide
    /// (`b4+P`), and isotope peaks form clusters
    #[test]
    fn annotates_a_crosslink_request() {
        let proforma = "GLEK[+138.06808#XL1]VSTAAMQR//TDYHFPNEWK[#XL1]LIR";
        let mut mz = ions_of(proforma, 3);
        // the second isotope of the first ion, and noise
        mz.push(mz[0] + NEUTRON);
        mz.extend([333.333, 444.444]);
        mz.sort_by(f64::total_cmp);
        let peaks = Peaks { intensity: vec![100.0; mz.len()], mz, precursor_mz: None, ion_mobility: None };
        let request = json!({
            "Peptides": [residues("GLEKVSTAAMQR"), residues("TDYHFPNEWKLIR")],
            "LinkSite": [{"id": 0, "peptideId": 0, "linkSite": 3}, {"id": 0, "peptideId": 1, "linkSite": 9}],
            "peaks": [],
            "annotation": {
                "requestID": "7", "precursorCharge": 3, "precursorMZ": 1000.0, "modifications": [],
                "fragmentTolerance": {"tolerance": 10.0, "unit": "ppm"},
                "ions": [{"type": "BIon"}, {"type": "YIon"}],
                "crosslinker": {"modMass": 138.06808},
            }
        });
        let out = annotate(&request, &peaks, None).unwrap();
        let names: Vec<&str> = out["fragments"].as_array().unwrap().iter().map(|f| f["name"].as_str().unwrap()).collect();
        assert!(names.contains(&"b3"), "{names:?}");
        assert!(names.contains(&"b4+P"), "the link residue K4 carries peptide 2: {names:?}");
        assert!(names.contains(&"y2"), "{names:?}");
        let b4 = out["fragments"].as_array().unwrap().iter().find(|f| f["name"] == "b4+P" && f["peptideId"] == 0).unwrap();
        assert_eq!(b4["range"].as_array().unwrap().len(), 2);
        assert_eq!(b4["sequence"], "GLEK + TDYHFPNEWKLIR");
        assert!(b4["clusterInfo"][0]["error"].as_f64().unwrap().abs() < 1.0);
        // every peak is in a cluster; the isotope pair shares one of charge 1
        let peaks_out = out["peaks"].as_array().unwrap();
        assert_eq!(peaks_out.len(), peaks.mz.len());
        assert!(peaks_out.iter().all(|p| !p["clusterIds"].as_array().unwrap().is_empty()));
        assert_eq!(peaks_out[0]["clusterIds"], peaks_out[1]["clusterIds"]);
        assert_eq!(out["clusters"][0]["charge"], 1);
        assert_eq!(out["annotation"]["requestID"], "7");
        // both peptides and the linker: (1302.6564 + 1689.8158 + 138.0681 + 3 H+) / 3
        let calc = out["annotation"]["calculatedMZ"].as_f64().unwrap();
        let whole = PeptidoformIonSet::pro_forma(proforma, &mzcore::ontology::STATIC_ONTOLOGIES).unwrap().0;
        let parts: f64 = ["GLEKVSTAAMQR", "TDYHFPNEWKLIR"]
            .iter()
            .map(|p| PeptidoformIonSet::pro_forma(p, &mzcore::ontology::STATIC_ONTOLOGIES).unwrap().0.formulas()[0].monoisotopic_mass().value)
            .sum::<f64>();
        let _ = whole;
        assert!((calc - (parts + 138.06808 + 3.0 * PROTON) / 3.0).abs() < 1e-3, "{calc}");
        // noise is not annotated
        let noise = peaks_out.iter().position(|p| (p["mz"].as_f64().unwrap() - 333.333).abs() < 1e-6).unwrap();
        let noise_cluster = peaks_out[noise]["clusterIds"][0].as_u64().unwrap();
        assert!(out["fragments"].as_array().unwrap().iter().all(|f| f["clusterIds"].as_array().unwrap().iter().all(|c| c.as_u64() != Some(noise_cluster))));
    }

    /// Modifications in the request (`(oxidation)` with its mass) and a
    /// linear peptide
    #[test]
    fn annotates_a_modified_linear_request() {
        let mz = ions_of("PEPM[+15.9949]TIDEK", 2);
        let peaks = Peaks { intensity: vec![50.0; mz.len()], mz, precursor_mz: None, ion_mobility: None };
        let mut peptide = residues("PEPMTIDEK");
        peptide["sequence"][3]["Modification"] = json!("(oxidation)");
        let request = json!({
            "Peptides": [peptide], "LinkSite": [], "peaks": [],
            "annotation": {
                "requestID": "1", "precursorCharge": 2, "modifications": [{"id": "(oxidation)", "mass": 15.9949, "aminoAcids": ["*"]}],
                "fragmentTolerance": {"tolerance": "0.02", "unit": "Da"}, "ions": [{"type": "BIon"}, {"type": "YIon"}],
                "crosslinker": {"modMass": 0}
            }
        });
        let out = annotate(&request, &peaks, None).unwrap();
        let names: Vec<&str> = out["fragments"].as_array().unwrap().iter().map(|f| f["name"].as_str().unwrap()).collect();
        // b4 holds the oxidised M: found only if the modification is applied
        assert!(names.contains(&"b4") && names.contains(&"y5"), "{names:?}");
        assert_eq!(out["fragments"][0]["clusterInfo"][0]["errorUnit"], "Da");
    }

    /// xiSPEC's settings send their numbers as text
    #[test]
    fn reads_numbers_written_as_text() {
        let mz = ions_of("PEPTIDEK", 2);
        let request = json!({
            "Peptides": [residues("PEPTIDEK")], "LinkSite": [{"id": 0, "peptideId": 0, "linkSite": -1}],
            "peaks": mz.iter().map(|m| json!({"mz": m.to_string(), "intensity": "10"})).collect::<Vec<_>>(),
            "annotation": {
                "requestID": "settings_1", "precursorCharge": "2", "precursorMZ": "465.7",
                "modifications": [], "fragmentTolerance": {"tolerance": "10", "unit": "ppm"},
                "ions": [{"type": "BIon"}, {"type": "YIon"}], "crosslinker": {"modMass": "0"}
            }
        });
        let peaks = request_peaks(&request);
        assert_eq!(peaks.mz.len(), mz.len());
        let out = annotate(&request, &peaks, None).unwrap();
        assert!(out["fragments"].as_array().unwrap().len() >= 10, "{}", out["fragments"]);
        assert_eq!(out["annotation"]["requestID"], "settings_1");
    }

    #[test]
    fn tolerance_and_ions_from_requests() {
        assert_eq!(tolerance(&json!({"annotation": {"fragmentTolerance": {"tolerance": "15", "unit": "ppm"}}})), Tolerance::Ppm(-15.0, 15.0));
        assert_eq!(tolerance(&json!({"annotation": {"fragmentTolerance": {"tolerance": 0.02, "unit": "Da"}}})), Tolerance::Da(-0.02, 0.02));
        let ions = Ions::from_request(Some(&json!([{"type": "PeptideIon"}, {"type": "BIon"}, {"type": "YIon"}])));
        assert!(ions.precursor && ions.series.contains(&'b') && ions.series.contains(&'y'));
        assert!(std::ptr::eq(ions.model(), FragmentationModel::cid()));
        let none = Ions::from_request(None);
        assert_eq!(none.series.iter().collect::<String>(), "by");
    }
}
